extern "C" void *memmove(void *, const void *, unsigned int);
extern "C" void *arch_malloc(unsigned int, const char *, int);
extern "C" void arch_free(void *);

template<class T>
class my_allocator
{
public:
  static T *allocate(unsigned int n)
  {
    return n ? (T *)arch_malloc(n * sizeof(T), __FILE__, 0) : 0;
  }

  static void deallocate(T *p, unsigned int)
  {
    if (p)
      arch_free(p);
  }
};

template<class T1, class T2>
inline void construct(T1 *p, const T2 &value)
{
  if (p)
    *p = value;
}

template<class T>
inline T *copy(const T *first, const T *last, T *result)
{
  memmove(result, first, sizeof(T) * (last - first));
  return result + (last - first);
}

template<class T>
inline T *copy_backward(const T *first, const T *last, T *result)
{
  unsigned int count = last - first;
  memmove(result - count, first, sizeof(T) * count);
  return result - count;
}

template<class T>
inline T *uninitialized_copy(const T *first, const T *last, T *result)
{
  return copy(first, last, result);
}

template<class T>
inline T *uninitialized_fill_n(T *first, unsigned int n, const T &x)
{
  while (n--)
    construct(first++, x);
  return first;
}

template<class T>
inline void fill(T *first, T *last, const T &x)
{
  while (first != last)
    *first++ = x;
}

template<class T>
inline void destroy(T *, T *)
{
}

template<class T>
inline const T &max(const T &a, const T &b)
{
  return a < b ? b : a;
}

template<class T, class Alloc>
class vector
{
protected:
  T *start_;
  T *finish_;
  T *end_of_storage_;

  T *allocate(unsigned int n) { return Alloc::allocate(n); }
  void deallocate(T *p, unsigned int n) { Alloc::deallocate(p, n); }

public:
  typedef T *iterator;
  typedef unsigned int size_type;

  iterator begin() { return start_; }
  iterator end() { return finish_; }
  size_type size() const { return finish_ - start_; }
  void insert(iterator position, size_type n, const T &x);
};

template<class T, class Alloc>
void vector<T, Alloc>::insert(iterator position, size_type n, const T &x)
{
  if (n != 0) {
    if (size_type(end_of_storage_ - finish_) >= n) {
      T x_copy = x;
      const size_type elems_after = finish_ - position;
      iterator old_finish = finish_;
      if (elems_after > n) {
        uninitialized_copy(finish_ - n, finish_, finish_);
        finish_ += n;
        copy_backward(position, old_finish - n, old_finish);
        fill(position, position + n, x_copy);
      } else {
        uninitialized_fill_n(finish_, n - elems_after, x_copy);
        finish_ += n - elems_after;
        uninitialized_copy(position, old_finish, finish_);
        finish_ += elems_after;
        fill(position, old_finish, x_copy);
      }
    } else {
      const size_type old_size = size();
      const size_type len = old_size + max(old_size, n);
      iterator new_start = allocate(len);
      iterator new_finish = new_start;
      new_finish = uninitialized_copy(start_, position, new_start);
      new_finish = uninitialized_fill_n(new_finish, n, x);
      new_finish = uninitialized_copy(position, finish_, new_finish);
      destroy(start_, finish_);
      deallocate(start_, end_of_storage_ - start_);
      start_ = new_start;
      finish_ = new_finish;
      end_of_storage_ = new_start + len;
    }
  }
}

class morphable_item_range;

template void vector<morphable_item_range *, my_allocator<morphable_item_range *> >::insert(
  morphable_item_range **, unsigned int, morphable_item_range * const &);
